body_md:
We say that $A$ is a \emph{$(W,*)$-algebra}, or a \emph{$W$-algebra with involution $*$}, if $A$ is a $(W,*)$-bimodule satisfying the following associative relations: for all $w\in W$, $ a_1,a_2\in A$,
\begin{align}\label{eq: compat}
		w(a_1a_2)=(wa_1)a_2, \quad
		(a_1a_2)w=a_1(a_2w), \quad
		(a_1w)a_2=a_1(wa_2).
\end{align}

Define $\mathcal{M}(A)$ as the subset of $ \operatorname{End}_F^{\operatorname{op}}(A) \times \operatorname{End}_F(A)$ of the pairs $(R,L)$ satisfying,
for all $a,b \in A$,
\begin{equation}\label{eq: comp L,R}
R(ab) = aR(b), \quad L(ab) = L(a)b, \quad R(a)b = aL(b).
\end{equation}
We refer to $R$ and $L$ as a \emph{right} and \emph{left multiplier} of $A$, respectively, and to the elements of $\mathcal{M}(A)$ as \emph{multipliers} of $A$.

A right multiplier $R$ and a left multiplier $L$ of $A$ are \emph{permutable} if
\begin{equation}\label{eq: permutability}
RL = LR.
\end{equation}

\label{ex: non permutable}
    Let $A=Fe_{12}\oplus Fe_{13} \oplus Fe_{23}$, where the $e_{ij}$’s are the usual matrix units. Consider the multiplier  $(R,L)\in \mathcal{M}(A)$ defined by
    \begin{equation*}
        \begin{split}
            R(e_{12})=e_{12}, \quad R(e_{13})=0, \quad R(e_{23})=e_{13},\\
            L(e_{12})=e_{13}, \quad L(e_{13})=0, \quad L(e_{23})=e_{23}.
        \end{split}
    \end{equation*}
Then $R$ and $L$ are not permutable. Indeed, $ R(L(e_{12}))=R(e_{13})=0,$ whereas $L(R(e_{12}))=L(e_{12})=e_{13}.$ Notice also that $(R,L)\notin \mathcal{I}\mathcal{M}(A)$. Indeed, suppose there exists $m=\alpha e_{12} + \beta  e_{13} + \gamma e_{23}\in A$ such that $(R,L)=(R_m,L_m)$, then applying the right multiplier to $e_{12}$, we obtain $e_{12}=\gamma e_{13}$,  which is a contradiction.

\label{def: equivalence}
We say that $(W,*)$-algebra structures $A^\Phi$ and
$A^{\Phi'}$ are \emph{equivalent} if $\Phi(W)=\Phi'(W)$ as $*$-subalgebras of $\mathcal{M}(A)$.

\label{th: *-simple characterization}
            Let $F$ be an algebraically closed field of characteristic zero. Then, up to isomorphisms, all finite dimensional $*$-simple algebras are the following ones
 		\begin{itemize}
 			\item $(M_n(F),t)$, the algebra of $n \times n$ matrices with transpose involution;
 			\item $(M_{2k}(F),s)$, the algebra of $2k \times 2k$ matrices with symplectic involution;
 			\item $(M_n(F)\oplus M_n(F)^{op},ex)$, the direct sum of the algebra of $n\times n$ matrices and its opposite algebra with the exchange involution.
 		\end{itemize}

If $A$ is a finite dimensional $(W,*)$-simple algebra over an algebraically closed field $F$ of characteristic zero, then $A$ is isomorphic to one of the following $(W,*)$-algebras:
 			\begin{itemize}
 				\item $M_n(F)$ with transpose or symplectic involution,
 				\item $M_n(F)\oplus M_n(F)^{op}$ with exchange involution $(a,b)^*=(b,a)$,
 			\end{itemize}
 			with the $W$-action given by left and right multiplication of an appropriate unital $*$-subalgebra.

Since $W$ is a $*$-algebra, we can consider a basis $\mathcal{B}_W$ of $W$ which is the union $\mathcal{B}_W=\mathcal{B}_{W^+}\cup \mathcal{B}_{W^-}$ of bases of $W^+$ and $W^-$, respectively, where $\mathcal{B}_{W^+}:=\{w_i^+ \, : \, i\geq 1\}$ and $\mathcal{B}_{W^-}:=\{w_i^- \, : \, i\geq 1\}$. Then, for $n \geq 1$ we can write
    \begin{align*}
        P_n^{W,*} = \operatorname{span}_F\{w_{i_0}^{\eta_0}x_{\sigma (1)}^{\epsilon_1} w_{i_1}^{\eta_1}x_{\sigma(2)}^{\epsilon_2}w_{i_2}^{\eta_2}\cdots w_{i_{n-1}}^{\eta_{n-1}}x_{\sigma(n)}^{\epsilon_n}w_{i_{n}}^{\eta_n}\, : \, \epsilon_k,\eta_l\in \{+,-\},\, w_{i_l}^{\eta_l}\in \mathcal{B}_{W^{\eta_l}},  \ \ \ &\\
         1\leq k \leq n,\, 0\leq l \leq n,\, \sigma \in S_{n}  &\ \}.
    \end{align*}

Let $\Phi$ denote the acting homomorphism of $W$ on $M^D$. Then $\Phi(W)\cong D$ and we can choose a basis $\mathcal{B}_W=\mathcal{B}_{W^+}\cup \mathcal{B}_{W^-}$  of $W=W^+\oplus W^-$, where $\mathcal{B}_{W^+}:=\{ w_i^+\, : \, i\geq 0\}$ and  $\mathcal{B}_{W^-}:=\{w_i^-\, : \, i\geq 1\}$ are basis of $W^+$ and $W^-$, respectively,  such that $w_0^+=1_W$,
 $$\Phi(w_1^+)=(R_{e_{11}+e_{44}-e_{22}-e_{33}},L_{e_{11}+e_{44}-e_{22}-e_{33}})\in \mathcal{M}(M) \qquad \mbox{and} \qquad w_i^+,\, w_j^-\in \ker \Phi \quad  \mbox{for all} \ i \geq 2, \, j\geq 1.$$ 
    Let $I$ be the $T_W^*$-ideal generated by the $(W,*)$-polynomials in the statement. It is easy to check that
            $I \subseteq \operatorname{Id}^{W,*}(M^D)$. 

            To prove the opposite inclusion, let $f$ be a multilinear generalized $*$-polynomial of degree $n$ and assume, as we may, that $f\in P_{r,n-r}$ for some $0\leq r \leq n$.


            Let $\epsilon\in \{+,-\}$. Observe first that $x^\epsilon (w_1^+)^2 - x^\epsilon \in \langle (w_1^+)^2x^\epsilon - x^\epsilon\rangle_{T_W^*}$. Moreover, for $i\geq 2$ we have $x^{\epsilon}w_i^+, \, w_1^+w_i^+x^\epsilon, \, x^{\epsilon}w_i^+w_1^+ \in \langle w_i^+x^\epsilon\rangle_{T_W^*}$ and for $j\geq 1$ we have $x^{\epsilon}w_j^-, \, w_1^+w_j^-x^\epsilon, \, x^{\epsilon}w_j^-w_1^+\in \langle w_j^-x^\epsilon\rangle_{T_W^*}$. Furthermore since the $(W,*)$-polynomial $w_1^+ x^{\epsilon}+ x^{\epsilon}w_1^+$ is symmetric if $\epsilon = +$ and skew-symmetric if $\epsilon = -$, it follows that $x^{\epsilon}w_1^+w_i^+, \, w_i^+w_1^+x^\epsilon\in \langle w_i^+x^\epsilon\rangle_{T_W^*}$ for all $i\geq 2$, and $x^{\epsilon}w_1^+w_j^-, \, w_j^-w_1^+ x^\epsilon\in \langle w_j^-x^\epsilon\rangle_{T_W^*}$ for all $j\geq 1$. Hence, since $(w_1^+)^2 x^\epsilon - x^\epsilon,
            \,  w_i^+x^\epsilon, \, w_j^-x^\epsilon\in I$, for $\epsilon\in \{+,-\}$, $i\geq 2$ and $j\geq 1$,  we may suppose that, modulo $I$,  only $1_W$ and $w_1^+$ appear in $f$. 


            Since $  [x^+_1, w_1^+]\in W\langle X, *\rangle^-$, by Lemma \ref{Lem: consequence x_1^- x_2^-} we get that for every $k\geq 0$
    \begin{equation*}
        [x^+_{k+1}, w_1^+] x_1^+ \cdots x_k^+ x_{k+2}^-, \quad  x^-_{k+2} x_1^+ \cdots x_k^+ [x_{k+1}^+,w_1^+]  \;\in I.
    \end{equation*} 
      Hence, using $ w_1^+x^-+x^-w_1^+, \, (w_1^+)^2 x^\epsilon - x^\epsilon, \, x^\epsilon (w_1^+)^2 - x^\epsilon\in I$, with $\epsilon\in \{ +,-\}$, we obtain for every $k\geq 0$
    \begin{equation}\label{eq: consequence w_1 1}
          v_{0}x_1^+ v_{1}x_2^+ \cdots v_{k-1} x_k^+ v_{k} x_{k+1}^- v_{k+1} \equiv x_1^+\cdots  x_k^+  x_{k+1}^- v \pmod{I}
    \end{equation}
    and
    \begin{equation}\label{eq: consequence w_1 2}
          v_{0} x_{k+1}^- v_{1} x_1^+ v_{2}x_2^+\cdots v_{k} x_k^+ v_{k+1}   \equiv x_{k+1}^-  x_1^+\cdots  x_k^+ v \pmod{I}
    \end{equation}
    where  $v, v_{0}, \ldots, v_{k+1}\in \{1_W, w_1^+\}$.




  Now, combining Lemma \ref{Lem: consequence x_1^- x_2^-} with \eqref{eq: consequence w_1 1}, we get for every $k\geq 0$
    \begin{equation}\label{eq: consequences}
        u_1x_{k+1}^- v_{0}x_1^+ v_{1}x_2^+\cdots v_{k-1} x_k^+ v_{k} x_{k+2}^- u_2\in I,
    \end{equation}
where  $u_1, u_2, v_{0}, \ldots, v_{k+1}\in \{1_W, w_1^+\}$. Thus, it follows that, modulo $I$, every monomial appearing in $f$ contains at most one variable of type $x^-$. In particular, either  $f\in P_{n-1,1}$ or $f\in P_{n,0}.$



 	Let us first consider $f\in P_{n-1,1}$. From  \eqref{eq: consequence w_1 1} and  \eqref{eq: consequence w_1 2} it follows that we can move $w_1^+$ to the end of each monomial of $f$. Moreover, by Lemma \ref{Lem: consequence x_1^- x_2^-} (see \cite[Remark 2]{MisVal}), in every monomial $x_{i_1}^+\cdots x_{i_{k}}^+x_{n}^-x_{j_{1}}^+ \cdots x_{j_{n-1-k}}^+$ we can reorder the variables to the left and to the right of $x_{n}^-$.
    Thus, we can write $f$, modulo $I$, as linear combination of the $(W,*)$-polynomials
    \begin{equation}\label{eq: generators P_n-1,1}
        x_{i_1}^+\cdots x_{i_{k}}^+x_{n}^-x_{j_{1}}^+ \cdots x_{j_{n-k-1}}^+, \quad x_{i_1}^+\cdots x_{i_{k}}^+x_{n}^-x_{j_{1}}^+ \cdots x_{j_{n-k-1}}^+w_1^+
    \end{equation}
     where $0\leq k \leq n-1$, $i_1< \ldots < i_k$ and $j_1< \ldots < j_{n-k-1}$.


Next, we prove that $(W,*)$-polynomials in \eqref{eq: generators P_n-1,1} are linearly independent modulo $\operatorname{Id}^{W,*}(M^D).$ To this end, let us assume that $f\in \operatorname{Id}^{W,*}(M^D)$ is a linear combination of the above $(W,*)$-polynomials, i.e.,
$$
f=\sum_{\mathcal{I}, \mathcal{J}} \alpha_{\mathcal{I}, \mathcal{J}} x_{i_1}^+\cdots x_{i_{k}}^+x_{n}^-x_{j_{1}}^+ \cdots x_{j_{n-k-1}}^+ + \sum_{\mathcal{I}, \mathcal{J}} \beta_{\mathcal{I}, \mathcal{J}} x_{i_1}^+\cdots x_{i_{k}}^+x_{n}^-x_{j_{1}}^+ \cdots x_{j_{n-k-1}}^+w_1^+
$$
where $\mathcal{I}=\{i_1, \ldots, i_k\}$ and $\mathcal{J}=\{j_1,\ldots, j_{n-k-1}\}$ are subsets of indices in $\{1,\ldots, n-1\}$ such that $\mathcal{I}\cap \mathcal{J}=\emptyset$ with $0\leq k \leq n-1$, $i_1< \cdots < i_k$, $j_1< \cdots < j_{n-k-1}$, and $\alpha_{\mathcal{I},\mathcal{J}}, \beta_{\mathcal{I},\mathcal{J}}\in F$ for all $\mathcal{I}, \mathcal{J}$.

Let $\mathcal{I}=\{i_1, \ldots, i_k\}$ and $\mathcal{J}=\{j_1,\ldots, j_{n-k-1}\}$ be two fixed disjoint subsets of $\{1,\ldots, n-1\}$ such that $0<k < n-1$, $i_1< \cdots < i_k$, $j_1< \cdots < j_{n-k-1}$.
If we make the evaluation $ x_{i_1}^+=\cdots =x_{i_{k}}^+= e_{11}+e_{44}$, $x_{j_{1}}^+ =\cdots= x_{j_{n-k-1}}^+= e_{22}+e_{33}$, and $x_n^-=e_{12}-e_{34}$, we get $(\alpha_{\mathcal{I}, \mathcal{J}} - \beta_{\mathcal{I}, \mathcal{J}})e_{12}-(\alpha_{\mathcal{J}, \mathcal{I}} + \beta_{\mathcal{J}, \mathcal{I}}) e_{34} =0$,  that is
\begin{equation}\label{eq: evaluation 1}
    \alpha_{\mathcal{I}, \mathcal{J}} - \beta_{\mathcal{I}, \mathcal{J}}=0 \quad \text{and} \quad \alpha_{\mathcal{J}, \mathcal{I}} + \beta_{\mathcal{J}, \mathcal{I}}=0.
\end{equation}
Moreover, let us make the evaluation $ x_{i_1}^+=\cdots =x_{i_{k}}^+= e_{22}+e_{33}$, $x_{j_{1}}^+ =\cdots= x_{j_{n-k-1}}^+= e_{11}+e_{44}$, and $x_n^-=e_{12}-e_{34}$. In this case we get $-(\alpha_{\mathcal{I}, \mathcal{J}} + \beta_{\mathcal{I}, \mathcal{J}})e_{34}+(\alpha_{\mathcal{J}, \mathcal{I}} - \beta_{\mathcal{J}, \mathcal{I}}) e_{12} =0$,  thus
\begin{equation}\label{eq: evaluation 2}
   \alpha_{\mathcal{I}, \mathcal{J}} + \beta_{\mathcal{I}, \mathcal{J}}=0 \quad \text{and} \quad \alpha_{\mathcal{J}, \mathcal{I}} - \beta_{\mathcal{J}, \mathcal{I}}=0.
\end{equation}
Hence, by putting together \eqref{eq: evaluation 1} and \eqref{eq: evaluation 2} we obtain that $ \alpha_{\mathcal{I}, \mathcal{J}} = \beta_{\mathcal{I}, \mathcal{J}}=\alpha_{\mathcal{J}, \mathcal{I}} = \beta_{\mathcal{J}, \mathcal{I}}=0$.



Finally, fixed $\mathcal{I}=\{1,\ldots,n-1\}$, if we evaluate $x_1=\cdots = x_{n-1}=e_{11}+e_{44}$ and $x_n^-=e_{12}-e_{34}$, then we get $(\alpha_{\mathcal{I}, \emptyset} - \beta_{\mathcal{I}, \emptyset})e_{12}-(\alpha_{\emptyset, \mathcal{I}} + \beta_{\emptyset, \mathcal{I}}) e_{34} =0$,  thus
\begin{equation}\label{eq: evaluation 3}
    \alpha_{\mathcal{I}, \emptyset} - \beta_{\mathcal{I}, \emptyset}=0 \quad \text{and} \quad \alpha_{\emptyset, \mathcal{I}} + \beta_{\emptyset, \mathcal{I}}=0.
\end{equation}
Moreover, from the evaluation $x_1=\cdots = x_{n-1}=e_{22}+e_{33}$ and $x_n^-=e_{12}-e_{34}$, it follows that $-(\alpha_{\mathcal{I}, \emptyset} + \beta_{\mathcal{I}, \emptyset})e_{34}+(\alpha_{\emptyset, \mathcal{I}} - \beta_{\emptyset, \mathcal{I}}) e_{12} =0$,  thus
\begin{equation}\label{eq: evaluation 4}
   \alpha_{\mathcal{I}, \emptyset} + \beta_{\mathcal{I}, \emptyset}=0 \quad \text{and} \quad \alpha_{\emptyset, \mathcal{I}} - \beta_{\emptyset, \mathcal{I}}=0.
\end{equation}
Therefore, putting together \eqref{eq: evaluation 3} and \eqref{eq: evaluation 4} we get  $\alpha_{\mathcal{I}, \emptyset}= \beta_{\mathcal{I}, \emptyset}=\alpha_{\emptyset, \mathcal{I}} = \beta_{\emptyset, \mathcal{I}}=0$. As a consequence, all the scalars appearing in $f$ are zero.

Thus, the polynomials in \eqref{eq: generators P_n-1,1} are linearly independent modulo $\operatorname{Id}^{W,*}(M^D)$ and, since $P_{n-1,1}\cap I\subseteq P_{n-1,1}\cap \operatorname{Id}^{W,*}(M^D),$ this proves that
the polynomials in \eqref{eq: generators P_n-1,1} are a basis of $P_{n-1,1}$ modulo $P_{n-1,1}\cap \operatorname{Id}^{W,*}(M^D).$ Hence, by counting we get
\begin{equation}\label{eq: c_{n-1,1}(M^D)}
    c_{n-1,1}(M^D)= 2 \sum_{k=0}^{n-1}\binom{n-1}{k}=2^n.
\end{equation}


Now, let us consider $f\in P_{n,0}$. Since $[x_1^+,x_2^+], [w_1^+, x_1^+] \in W\langle X,* \rangle^-$, from \eqref{eq: consequence w_1 1} we obtain for every $k\geq 0$
    \begin{align}\label{eq: consequence w_1 3}
          v_{0}x_1^+ v_{1}x_2^+\cdots v_{k-1} x_k^+ v_{k} [x_{k+1}^+,x_{k+2}^+] v_{k+1} &\equiv x_1^+\cdots  x_k^+  [x_{k+1}^+,x_{k+2}^+]  v \pmod{I},\\
          \label{eq: consequence w_1 3bis}
 v_{0}x_1^+ v_{1}x_2^+\cdots v_{k-1} x_k^+ v_{k} [w_1^+, x_{k+1}^+] v_{k+1} &\equiv x_1^+\cdots  x_k^+  [w_1^+, x_{k+1}^+]  v \pmod{I},
 \end{align}
 and from \eqref{eq: consequence w_1 2} we get for every $k\geq 0$
    \begin{align}
          \label{eq: consequence w_1 4}
          v_{0} [x_{k+1}^+,x_{k+2}^+] v_{1} x_1^+ v_{2}x_2^+\cdots v_{k} x_k^+ v_{k+1}   &\equiv [x_{k+1}^+,x_{k+2}^+]  x_1^+\cdots  x_k^+ v \pmod{I},\\
          \label{eq: consequence w_1 4 bis}
            v_{0} [w_1^+, x_{k+1}^+] v_{1} x_1^+ v_{2}x_2^+\cdots v_{k} x_k^+ v_{k+1}   &\equiv [w_1^+, x_{k+1}^+]  x_1^+\cdots  x_k^+ v \pmod{I}.
    \end{align}
    where  $v, v_{0}, \ldots, v_{k+1}\in \{1_W, w_1^+\}$. As a consequence, by the Poincaré-Birkhoff-Witt Theorem, $f$ can be written, modulo $I$, as a linear combination of polynomials of the type
    \begin{equation}\label{eq: PBW}
        x_{i_1}^+\cdots x_{i_m}^+c_1c_2\cdots c_s v,
    \end{equation}
    where $i_1<\cdots < i_m,$ $c_1,\ldots, c_s$ are left-normed commutators containing symmetric variables and $w_1^+$, and $v\in \{1_W, w_1^+\}$.


     Now, by  \eqref{eq: consequences} and again since $[x_1^+,x_2^+], [x_1^+,w_1^+]\in W\langle X,* \rangle^-$, we get for every $k\geq 0$
     \begin{align*}
          u_1[x_{k+1}^+,x_{k+2}^+] v_{0}x_1^+ v_{1}x_2^+\cdots v_{k-1} x_k^+ v_{k} [x_{k+3}^+,x_{k+4}^+]u_2 \, &\in I,\\
          u_1[w_1^+, x_{k+1}^+] v_{0}x_1^+ v_{1}x_2^+\cdots v_{k-1} x_k^+ v_{k} [x_{k+2}^+,x_{k+3}^+]u_2 \, &\in I,\\
          u_1[x_{k+1}^+,x_{k+2}^+] v_{0}x_1^+ v_{1}x_2^+\cdots v_{k-1} x_k^+ v_{k} [w_1^+, x_{k+3}^+]u_2 \, &\in I,\\
           u_1[w_1^+, x_{k+1}^+] v_{0}x_1^+ v_{1}x_2^+\cdots v_{k-1} x_k^+ v_{k} [w_1^+, x_{k+2}^+]u_2 \, &\in I,
          \end{align*}
where  $u_1, u_2, v_{0}, \ldots, v_{k}\in \{1_W, w_1^+\}$. Thus it follows that in \eqref{eq: PBW} only a left-normed commutator can appear, i.e., $s\in \{0,1\}$. Moreover, by \eqref{eq: consequence w_1 3}--\eqref{eq: consequence w_1 4 bis}, we can assume that if $w_1^+$ appears in the commutator $c_1$, then it is in the first position. Hence, $f$ can be written, modulo $I$, as a linear combination of $(W,*)$-monomials $x_1\cdots x_n v$ and the $(W,*)$-polynomials of the type
\begin{equation*}\label{eq: almost a basis}
    x_{i_1}^+\cdots x_{i_{m}}^+[x_{k}^+,x_{j_1}^+,\ldots, x_{j_{n-m-1}}^+]v, \quad x_{i_1}^+\cdots x_{i_{m}}^+[w_1^+, x_{l_1}^+,\ldots, x_{l_{n-m}}^+]v
\end{equation*}
 where $0\leq m \leq n-2$, $i_1<\cdots < i_m$ and $v\in \{1_W, w_1^+\}$.  Since $[x_{k}^+, x_{j_1}^+], [w_1^+,x_{l_1}^+]\in W \langle X,*\rangle^-$, Lemma \ref{Lem: consequence x_1^- x_2^-} implies that we can reorder the variables to the left and to the right of $[x_{k}^+,x_{j_1}^+]$ and $[w_1^+,x_{l_1}^+]$ (see \cite[Remark 2]{MisVal}). Hence we may assume that $j_2<  \cdots < j_{n-m-1}$ and  $l_2<  \cdots < l_{n-m}$.
 Moreover, by the Jacobi identity we may also suppose that $k>j_1<j_2$.  Additionally, applying the Jacobi identity, \eqref{eq: consequence w_1 3} and \eqref{eq: consequence w_1 4}, we may suppose that $l_1<l_2$. This implies that we can write $f$, modulo $I$, as linear combination of the $(W,*)$-polynomials
 \begin{equation}\label{eq: generators P_n,0}
 \begin{split}
      &  x_{i_1}^+\cdots x_{i_{m}}^+[x_{k}^+,x_{j_1}^+,\ldots, x_{j_{n-m-1}}^+], \quad  x_{i_1}^+\cdots x_{i_{m}}^+[x_{k}^+,x_{j_1}^+,\ldots, x_{j_{n-m-1}}^+]w_1^+ \\
  &  x_{h_1}^+\cdots x_{h_{p}}^+[w_1^+, x_{l_1}^+,\ldots, x_{l_{n-p}}^+], \quad  x_{h_1}^+\cdots x_{h_{p}}^+[w_1^+, x_{l_1}^+,\ldots, x_{l_{n-p}}^+]w_1^+,
 \end{split}
\end{equation}
where $0\leq m \leq n$, $m\neq n-1$, $0\leq p\leq n-1$, $i_1 < \cdots < i_m$, $k>j_1< \cdots < j_{n-m-1}$, $h_1< \cdots < h_p$, $l_1< \cdots < l_{n-p}$.


Next, we prove that these $(W,*)$-polynomials are linearly independent modulo $\operatorname{Id}^{W,*}(M^D)$. To this end, let us assume $f\in \operatorname{Id}^{W,*}(M^D)$ is such that
\begin{equation}\label{eq: id}
\begin{split}
     f= & \sum_{\mathcal{I}, k} \alpha_{\mathcal{I}, k} x_{i_1}^+\cdots x_{i_{m}}^+[x_{k}^+,x_{j_1}^+,\ldots, x_{j_{n-m-1}}^+] + \sum_{\mathcal{I}, k} \beta_{\mathcal{I}, k} x_{i_1}^+\cdots x_{i_{m}}^+[x_{k}^+,x_{j_1}^+,\ldots, x_{j_{n-m-1}}^+]w_1^+ \\
  & +\sum_{\mathcal{H}} \gamma_{\mathcal{H}} x_{h_1}^+\cdots x_{h_{p}}^+[w_1^+, x_{l_1}^+,\ldots, x_{l_{n-p}}^+]+ \sum_{\mathcal{H}} \delta_{\mathcal{H}} x_{h_1}^+\cdots x_{h_{p}}^+[w_1^+, x_{l_1}^+,\ldots, x_{l_{n-p}}^+]w_1^+,
\end{split}
\end{equation}
where $0\leq m \leq n$, $m\neq n-1$, $0\leq p\leq n-1$, $i_1< \cdots < i_m$, $k>j_1< \cdots < j_{n-m-1}$, $h_1< \cdots < h_p$, $l_1<\cdots < l_{n-p}$,  $\mathcal{I}=\{i_1, \ldots, i_m\}$, $\mathcal{H}=\{h_1,\ldots, h_p\}$ and $\alpha_{\mathcal{I}, k}, \beta_{\mathcal{I},k},\gamma_{\mathcal{H}}, \delta_{\mathcal{H}} \in F$ for all $\mathcal{I}, \mathcal{H}$.


First, suppose that $\alpha_{\mathcal{I},0} \neq 0$ or $\beta_{\mathcal{I},0} \neq 0$ in \eqref{eq: id}  with  $ \mathcal{I}=\{1,\ldots, n\}.$ From the evaluation $x_1^+=\cdots = x_n^+=e_{11}+e_{22}+e_{33}+e_{44}$ it follows that $\alpha_{\mathcal{I},0} (e_{11}+e_{22}+e_{33}+e_{44})+ \beta_{\mathcal{I},0}(e_{11}+e_{44}-e_{22}-e_{33})=0 $, thus $\alpha_{\mathcal{I},0} =\beta_{\mathcal{I},0}=0$, a contradiction. This says that in \eqref{eq: id} only terms with one commutator can appear with a non-zero coefficient.

Now, let $k\in \{1,\ldots, n\}$ and let $\mathcal{I}=\{i_1, \ldots, i_m\}$ be a proper subset of $\{1,\ldots, n\}\setminus\{k\}$ where $i_1<\cdots <i_m$ and $ 0 \leq m\leq n-2$ is the maximum such that $\alpha_{\mathcal{I},k} \neq 0$ or $\beta_{\mathcal{I},k}\neq 0$ in \eqref{eq: id}. If we consider the evaluation $x_{i_1}^+=\cdots =x_{i_m}^+=e_{11}+e_{22}+e_{33}+e_{44},$
$ x_{k}^+= e_{12}+e_{34},$  and $x_{j_1}^+=\cdots = x_{j_{n-m-1}}^+=e_{22}+e_{33},$ then the third and fourth summations in \eqref{eq: id} are evaluated to zero since $\Phi(w_1^+)(e_{22}+e_{33})- (e_{22}+e_{33})\Phi(w_1^+)=0$, and we get $$(\alpha_{\mathcal{I}, k} -  \beta_{\mathcal{I},k})e_{12} + (-1)^{n-m-1} (\alpha_{\mathcal{I}, k} +  \beta_{\mathcal{I},k}) e_{34} =0.$$
Thus $ \alpha_{\mathcal{I}, k} -  \beta_{\mathcal{I},k}=0$ and $\alpha_{\mathcal{I}, k} +  \beta_{\mathcal{I},k}=0.$
As a consequence, it follows that $\alpha_{\mathcal{I}, k}= \beta_{\mathcal{I},k}=0$, a contradiction. By repeating this argument we obtain that $\alpha_{\mathcal{I}, k}= \beta_{\mathcal{I},k}=0$ for all $\mathcal{I}$ and $k$.

Now suppose that $\mathcal{H}=\{h_1, \ldots, h_p\}$ is a proper subset of $\{1,\ldots, n\}$ where $h_1<\cdots <h_p$ and $ 0 \leq p\leq n-2$ is the maximum such that $\gamma_{\mathcal{H}} \neq 0$ or $\delta_{\mathcal{H}}\neq 0$ in \eqref{eq: id}, and consider the evaluation $x_{h_1}^+=\cdots =x_{h_p}^+=e_{11}+e_{22}+e_{33}+e_{44},$
$ x_{l_1}^+= e_{12}+e_{34},$  and $x_{l_2}^+=\cdots = x_{l_{n-p}}^+=e_{22}+e_{33}.$ Under this evaluation, we obtain
$$2(\gamma_{\mathcal{H}} -  \delta_{\mathcal{H}})e_{12} + 2(-1)^{n-p-1} (\gamma_{\mathcal{H}} +  \delta_{\mathcal{H}}) e_{34} =0.$$
As a consequence, since $\operatorname{char} F=0$, we get that $\gamma_{\mathcal{H}}=  \delta_{\mathcal{H}}=0$, a contradiction. As above, by repeating this argument we obtain that $\gamma_{\mathcal{H}}=  \delta_{\mathcal{H}}=0$ for all $\mathcal{H}$. As a consequence, all the scalars appearing in $f$ are zero, i.e., $f=0.$

Thus, the polynomials in \eqref{eq: generators P_n,0} are linearly independent modulo $\operatorname{Id}^{W,*}(M^D)$ and,
as in the previous case, this implies that the $(W,*)$-polynomials in \eqref{eq: generators P_n,0} are a basis of $P_{n,0}$ modulo $P_{n,0}\cap \operatorname{Id}^{W,*}(M^D).$ Hence, by counting we get
\begin{equation}\label{eq: c_{n,0}(M^D)}
    c_{n,0}(M^D)= 2+2\sum_{m=2}^n\binom{n}{m}(m-1)+ 2\sum_{m=0}^{n-1}\binom{n}{m}=2\sum_{m=0}^n\binom{n}{m}m +2= n2^n +2.
\end{equation}

Since we have shown that $P_{r,n-r}\cap \operatorname{Id}^{W,*}(M^D) \supseteq P_{r,n-r}\cap I$  for all $n\in\mathbb{N}$ and $0\leq r\leq n$, it follows that $\operatorname{Id}^{W,*}(M^D)=I$, as claimed.



Finally, since $P_{r,n-r}\equiv 0 \pmod{(P_{r,n-r}\cap \operatorname{Id}^{W,*}(M^D))}$ for $0\leq r \leq n-2$, applying Formula~\eqref{eq: decomp codim} together with \eqref{eq: c_{n-1,1}(M^D)} and \eqref{eq: c_{n,0}(M^D)}, we obtain
\begin{align*}
 	c_n^{W,*}(M^D)=\sum_{r=0}^n\binom{n}{r}c_{r,n-r}^{W,*}(M^D)=c_{n,0}^{W,*}(M^D)+ n c_{n-1,1}^{W,*}(M^D)=n2^{n}+2+ n  2^{n}= n2^{n+1}  +2,
 	\end{align*}
    as desired.

\label{lemma: cn-1,1}
 If $r=n-1$, then in \eqref{eq: ch M^D} we have 
$$
m_{\lambda,\mu}= \begin{cases}
             2(q+1)  & \text{if } \lambda=(p+q,p),  \mu=(1)\\
              2n & \text{if }  \lambda=(n-1),  \mu=(1)\\
            0 & \text{otherwise}
    \end{cases}.
$$

We proceed as in the proof of the previous lemma. Observe that, in this case, as a consequence of formula \eqref{eq: codim and ch M^D}, it is enough to prove that:
\begin{enumerate}
\item $m_{(p+q,p),\emptyset}\geq 4(q+1)$ for all $p \geq 1$ and $q \geq 0$ such that $2p+q=n$;
\vspace{1mm}
\item $m_{(p+q,p,1),\emptyset}\geq 2(q+1)$ for all $p \geq 1$ and $q \geq 0$ such that $2p+q=n-1$;
\vspace{1mm}
\item $m_{(n),\emptyset}\geq 2n+2$.
\end{enumerate}
Indeed, if these conditions hold, then  
\begin{equation}\label{eq: c_{n,0}(M^D) diseq}
		  c_{n,0}(M^D) 
          \geq\sum_{\substack{1\leq p \leq \lfloor \frac{n}{2}\rfloor\\0 \leq q \leq n-2p}}4(q+1)d_{(p+q,p)}d_{\emptyset}+\sum_{\substack{1\leq p \leq \lfloor \frac{n-1}{2}\rfloor\\0 \leq q \leq n-2p-1}}2(q+1)d_{(p+q,p,1)}d_{\emptyset}+(2n+2) d_{(n)}d_{\emptyset}. 
	\end{equation}
Notice that by the formulas $(4.8)$ and $(4.9)$ proved in Theorem 4.4 of \cite{MarRiz2}, we have
$$
  \sum_{ \substack{ 1 \leq p \leq \lfloor\frac{n}{2}\rfloor \\ 0 \leq q \leq n-2p}}  4(q+1) d_{(p+q,p)}=2^{n+2}-4n-4.
$$
and
$$
\sum_{ \substack{ 1 \leq p \leq \lfloor\frac{n-1}{2}\rfloor \\ 0 \leq q \leq n-2p-1}}  2(q+1) d_{(p+q,p,1)} =  (n-4)2^{n}+2n+4.
$$
Hence, recalling that $d_{(n)}=d_{\emptyset}=1$, we obtain
\begin{equation*}
    \sum_{\substack{1\leq p \leq \lfloor \frac{n}{2}\rfloor\\0 \leq q \leq n-2p}}4(q+1)d_{(p+q,p)}d_{\emptyset}+\sum_{\substack{1\leq p \leq \lfloor \frac{n-1}{2}\rfloor\\0 \leq q \leq n-2p-1}}2(q+1)d_{(p+q,p,1)}d_{\emptyset}+(2n+2) d_{(n)}d_{\emptyset}                                    
    =n 2^n +2.
\end{equation*}
Since, by \eqref{eq: c_{n,0}(M^D)}, we have $c_{n,0}(M^D)=n2^n+2$, it follows that \eqref{eq: c_{n,0}(M^D) diseq} is in fact an equality. Thus it remains to prove the three inequalities above.

\vspace{1ex}
We now compute the three cases separately.


\vspace{1ex}

     \noindent\textbf{Case 1:} We prove that $m_{(p+q,p), \emptyset}\geq 4(q+1)$ for all $p \geq 1$ and $q \geq 0$ such that $2p+q=n$.


		For $0\leq i \leq q$, we consider the tableau
		\begin{equation*}
			T_{(p+q,p)}^{(i)}=\begin{array}{|c|c|c|c|c|c|c|c|c|c|c|}
				\hline
				i+1 & i+2 & \dots & i+p-1 & i+p & 1 & \dots & i & i+2p+1 & \dots & n\\
				\hline
				i+p+2 & i+p+3 & \dots & i+2p & i+p+1\\   
				\cline{1-5}
			\end{array}
		\end{equation*}
		and its associated $(W,*)$-polynomials

    	\begin{align}
	    f_{p,q}^{(i)}(x_1^+,x_2^+)&=(x_1^+)^i\underbrace{\overline{x_1^+}\cdots\widetilde{x_1^+}}_{p-1}[x_1^+,x_2^+]\underbrace{\overline{x_2^+}\cdots \widetilde{x_2^+}}_{p-1}(x_1^+)^{q-i},\label{eq: f}\\
		f_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)&=(x_1^+)^i\underbrace{\overline{x_1^+}\cdots\widetilde{x_1^+}}_{p-1}[x_1^+,x_2^+]\underbrace{\overline{x_2^+}\cdots \widetilde{x_2^+}}_{p-1}(x_1^+)^{q-i}w_1^+,\label{eq: fw_1}\\
		g_{p,q}^{(i)}(x_1^+,x_2^+)&=(x_1^+)^i\underbrace{\overline{x_1^+}\cdots\widetilde{x_1^+}}_{p-1}(x_1^+w_1^+ x_2^+-x_2^+w_1^+x_1^+)\underbrace{\overline{x_2^+}\cdots \widetilde{x_2^+}}_{p-1}(x_1^+)^{q-i},\label{eq: gi}\\
		g_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)&=(x_1^+)^i\underbrace{\overline{x_1^+}\cdots\widetilde{x_1^+}}_{p-1}(x_1^+w_1^+ x_2^+-x_2^+w_1^+x_1^+)\underbrace{\overline{x_2^+}\cdots \widetilde{x_2^+}}_{p-1}(x_1^+)^{q-i}w_1^+,\label{eq: gw_1}
	\end{align}
		where the symbol $\tilde{\phantom{a}}$ or $\overline{\phantom{a}}$ means alternation on the corresponding variables.  For any $0\leq i \leq q$, these $(W,*)$-polynomials are obtained 
        from the quasi-idempotents corresponding to the tableau $T_{(p+q,p)}^{(i)}$ by identifying all the elements in each row. 

        Clearly, the $4(q+1)$ polynomials $f_{p,q}^{(i)}(x_1^+,x_2^+)$, $f_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)$, $g_{p,q}^{(i)}(x_1^+,x_2^+)$, $g_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)$, for all $0\leq i \leq q$, do not belong to $\operatorname{Id}^{W,*}(M^D)$. 
        Next, we will prove that they are linearly independent modulo $\operatorname{Id}^{W,*}(M^D)$.

		Suppose that
        $$
        \sum_{i=0}^q \alpha_i f_{p,q}^{(i)}(x_1^+,x_2^+)+\sum_{i=0}^q\beta_i f_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)+ \sum_{i=0}^q\gamma_i g_{p,q}^{(i)}(x_1^+,x_2^+)+ \sum_{i=0}^q\delta_i g_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)\equiv 0 \pmod{\operatorname{Id}^{W,*}(M^D)}.
        $$

        If we evaluate $x_1^+=k(e_{11}+e_{44})+e_{22}+e_{33}+e_{12}+e_{34}$, with $k \in F$, $k \neq 0$, and $x_2^+=e_{11}+e_{44}$, we get 
         \begin{equation}\label{eq: eval ch p+q,p 1}
         (-1)^{p-1} \left(\sum_{i=0}^q (-\alpha_i  + \beta_i   -\gamma_i  +\delta_i) k^i\right) e_{12}+ \left( \sum_{i=0}^q (\alpha_i+\beta_i+\gamma_i+ \delta_i)k^{q-i}\right)e_{34}=0.
        \end{equation}
        Also, by evaluating $x_1^+=e_{11}+e_{44}+k(e_{22}+e_{33})+e_{12}+e_{34}$, with $k \in F$, $k \neq 0$, and $x_2^+=e_{22}+e_{33}$, we obtain 
         \begin{equation}\label{eq: eval ch p+q,p 2}
         \left(\sum_{i=0}^q (\alpha_i-\beta_i-\gamma_i+\delta_i)k^{q-i}\right) e_{12} +(-1)^{p-1}\left( \sum_{i=0}^q(-\alpha_i-\beta_i+\gamma_i+\delta_i)k^{i}\right) e_{34}=0.
        \end{equation}
        Hence, setting $t=q-i$ and from \eqref{eq: eval ch p+q,p 1}, \eqref{eq: eval ch p+q,p 2} it follows that
        \begin{align*}
        &\sum_{i=0}^q k^i(-\alpha_i  + \beta_i   -\gamma_i  +\delta_i) =0, \quad \quad   \sum_{t=0}^q k^{t}(\alpha_{q-t}+\beta_{q-t}+\gamma_{q-t}+ \delta_{q-t})=0,\\
          & \sum_{t=0}^q k^{t} (\alpha_{q-t}-\beta_{q-t}-\gamma_{q-t}+\delta_{q-t})=0,  \quad \quad \sum_{i=0}^q k^{i}(-\alpha_i-\beta_i+\gamma_i+\delta_i)=0.
        \end{align*}

        Now, for $0\leq i \leq q$, let 
        \begin{equation}\label{eq: eta}
        \begin{split}
             &\eta_i^{(1)}:=-\alpha_i  + \beta_i   -\gamma_i  +\delta_i, \quad \quad  \eta_i^{(2)}:=\alpha_{q-i}+\beta_{q-i}+\gamma_{q-i}+ \delta_{q-i},\\
            &\eta_i^{(3)}:=\alpha_{q-i}-\beta_{q-i}-\gamma_{q-i}+\delta_{q-i}, \quad \quad \eta_i^{(4)}:=-\alpha_i-\beta_i+\gamma_i+\delta_i.
        \end{split}
        \end{equation}
        Given $1\leq j \leq 4$,  assume that there exists $\eta_i^{(j)}\neq 0$ for some $0\leq i \leq q$.  Since $F$ is an infinite field, we can choose $k_0,\dots,k_{q}\in F$ such that $k_i\neq 0$ and $k_i\neq k_j$ for $0\leq i \neq j \leq q$. Then, we get the following homogeneous linear system of $q+1$ equation in the $q+1$ variables $\eta_0^{(j)}, \ldots, \eta_q^{(j)}$
        $$
        \sum_{i=0}^q  k_s^i \eta_i^{(j)}=0, \quad \quad 0 \leq s \leq q.
        $$
        Since the matrix associated to the above system is a Vandermonde matrix, it follows that $\eta_i^{(j)}=0$ for any $0 \leq i \leq q$, a contradiction. Thus, by \eqref{eq: eta} we get that $\alpha_i=\beta_i=\gamma_i=\delta_i=0$ for all $0\leq i \leq q$. 

        Therefore, the $4(q+1)$ generalized $*$-polynomials $f_{p,q}^{(i)}(x_1^+,x_2^+)$, $f_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)$, $g_{p,q}^{(i)}(x_1^+,x_2^+)$, $g_{p,q, w_1^+}^{(i)}(x_1^+,x_2^+)$ are linearly independent modulo $\operatorname{Id}^{W,*}(M^D)$.


Proceeding as in the previous lemma, we observe that for every $0\leq i \leq q$, the complete linearizations of $f_{p,q}^{(i)}(x_1^+,x_2^+)$, $f_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)$, $g_{p,q}^{(i)}(x_1^+,x_2^+)$, and $g_{p,q, w_1^+}^{(i)}(x_1^+,x_2^+)$ are, respectively, the $(W,*)$-polynomials 
        $$e_{T_{(p+q,p)}^{(i)}}(x_1^+ \cdots x_{n}^+), \quad e_{T_{(p+q,p)}^{(i)}}(x_1^+ \cdots x_{n}^+ w_1^+),
        $$
        $$
        e_{T_{(p+q,p)}^{(i)}}(x_1^+ \cdots x_{i+p}^+ w_1^+ x_{i+p+1}^+ \cdots  x_{n}^+), \quad e_{T_{(p+q,p)}^{(i)}}(x_1^+ \cdots x_{i+p}^+ w_1^+ x_{i+p+1}^+ \cdots  x_{n}^+  w_1^+).$$
         Hence, these multilinear $(W,*)$-polynomials are also linearly independent modulo $\operatorname{Id}^{W,*}(M^D)$. Consequently, they generate $4(q+1)$ distinct copies of the same irreducible module corresponding to the pair of partitions $\big((p+q,p),\emptyset\big)$ in the module decomposition of $P_{n,0}(M^D)$. Therefore, we conclude that $m_{(p+q,p),\emptyset}\geq 4(q+1)$, as claimed.





		\vspace{1ex}

		\noindent\textbf{Case 2:} We prove that $m_{(p+q,p,1),\emptyset}\geq 2(q+1)$ for all $p \geq 1$ and $q \geq 0$ such that $2p+q=n-1$.

		For $0\leq i \leq q$, consider the tableau
		\begin{equation*}
			T_{(p+q,p,1)}^{(i)}=\begin{array}{|c|c|c|c|c|c|c|c|c|c|c|}
				\hline
				i+p & i+1 & \dots & i+p-1 & 1 & \dots & i & i+2p+2 & \dots & n\\
				\hline
				i+p+1 & i+p+3 & \dots &  i+2p+1\\   
				\cline{1-4}
				i+p+2\\
				\cline{1-1}
			\end{array}
		\end{equation*}
		and its associated $(W,*)$-polynomials
		\begin{align}
		   h_{p,q}^{(i)}(x_1^+,x_2^+,x_3^+)&=(x_1^+)^i\underbrace{\widehat{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\overline{x_1^+}\,\overline{x_2^+} \,\overline{x_3^+}\underbrace{\widehat{x_2^+}\cdots \widetilde{x_2^+}}_{p-1}(x_1^+)^{q-i},\label{eq: h}\\
		h_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+,x_3^+)&=(x_1^+)^i\underbrace{\widehat{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\overline{x_1^+}\,\overline{x_2^+} \,\overline{x_3^+}\underbrace{\widehat{x_2^+}\cdots \widetilde{x_2^+}}_{p-1}(x_1^+)^{q-i}w_1^+, \label{eq: hw_1}
		\end{align}
		 where the symbol $\hat{}$ or $\tilde{}$ or $\bar{}$ means alternation on the corresponding variables. For any $0\leq i \leq q$, each of these generalized $*$-polynomials is obtained from the quasi-idempotents corresponding to the tableau $T_{(p+q,p,1)}^{(i)}$ by identifying all the elements in each row.

         Clearly, $h^{(i)}_{p,q}(x_1^+,x_2^+,x_3^+)$,  $h_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+,x_3^+)$, for $0\leq i \leq q$,  do not belong to $\operatorname{Id}^{W,*}(M^D)$ and we will prove that they are linearly independent modulo $\operatorname{Id}^{W,*}(M^D)$.

         We proceed as in the previous case. So, assume that
         $$
        \sum_{i=0}^q \alpha_i h_{p,q}^{(i)}(x_1^+,x_2^+,x_3^+)+
        \sum_{i=0}^q \beta_i h_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+,x_3^+)\equiv 0 \pmod{\operatorname{Id}^{W,*}(M^D)}.
        $$
        With the same reasoning as before, if we evaluate first $x_1^+=k(e_{11}+e_{44})+e_{22}+e_{33}+e_{12}+e_{34}$, $x_2^+=e_{11}+e_{44}$, $x_3^+=e_{22}+e_{33}$ with $0\neq k \in F$, we get
        $$
        (-1)^{p} \left(\sum_{i=0}^q (\alpha_i-\beta_i)k^i  \right) e_{12}+ \left(\sum_{i=0}^q (\alpha_i+\beta_i)k^{q-i}  \right) e_{34} =0,
        $$
       and, as a consequence,
       $$
       \sum_{i=0}^q (\alpha_i-\beta_i)k^i =0, \quad \quad \sum_{i=0}^q (\alpha_i+\beta_i)k^{q-i}=0.
       $$
Now, by applying the same argument as in Case $1$ of the proof of Lemma \ref{lemma: cn-1,1}, it follows that $\alpha_i=\beta_i=0$ for all $0\leq i \leq q$. Hence the $2(q+1)$ generalized $*$-polynomials $h_{p,q}^{(i)}(x_1^+,x_2^+,x_3^+)$ and $h_{p,q, w_1^+}^{(i)}(x_1^+,x_2^+,x_3^+)$ are linearly independent modulo $\operatorname{Id}^{W,*}(M^D)$. 

Therefore, as in the previous case, we obtain $m_{(p+q,p,1), \emptyset}\geq 2(q+1)$, as claimed.









\vspace{1ex}

		\noindent \textbf{Case 3:} We prove that $m_{(n),\emptyset}\geq 2n+2$.

        Given the tableau
        \begin{equation*}
			T_{(n)}=\begin{array}{|c|c|c|c|c|c|c|c|c|c|c|}
				\hline
				1 & 2 & 3 & \dots & n\\  
				\hline
			\end{array}
		\end{equation*}
		and its associated polynomials
        \begin{align}
            t(x^+)&=(x^+)^n, \label{eq: t}\\
            t_{w_1^+}(x^+)&=(x^+)^nw_1^+,\label{eq: tw1}\\
            u^{(i)}(x^+)&=(x^+)^i[x^+,w_1^+](x^+)^{n-i-1}, \quad \quad  0\leq i\leq n-1, \label{eq: u}\\
            u_{w_1^+}^{(i)}(x^+)&=(x^+)^i[x^+,w_1^+](x^+)^{n-i-1}w_1^+,  \quad \quad  0\leq i\leq n-1, \label{eq: uw1}
        \end{align}
        These $(W,*)$-polynomials are obtained 
        from the quasi-idempotents corresponding to the tableau $T_{(n)}$ by identifying all the elements.


		We will prove that the $2n+2$ generalized $*$-polynomials $ t(x^+)$, $ t_{w_1^+}(x^+)$, $u^{(i)}(x^+)$,  and $u_{w_1^+}^{(i)}(x^+)$, for $0\leq i \leq n-1$, which are not $(W,*)$-identities of $M^D$, are linearly independent modulo $\operatorname{Id}^{W,*}(M^D)$. 

        Suppose that
        \begin{align*}
        \alpha t(x^+)+ \beta t_{w_1^+} (x^+)+\sum_{0 \leq i \leq n-1}\gamma_i u^{(i)}(x^+)+\sum_{0 \leq i \leq n-1} \delta_i u_{w_1^+}^{(i)} (x^+)\equiv 0 \pmod{\operatorname{Id}^{W,*}(M^D)}.
        \end{align*}

        First of all, note that if we evaluate them at $x^+=e_{11}+e_{44}+e_{22}+e_{33}$, then the last two sums vanish and we get
		$(\alpha+\beta)(e_{11}+e_{44})+(\alpha-\beta)(e_{22}+e_{33})= 0,$
		so $\alpha=\beta=0$.

		Now, we want to prove that the last two sums are also linearly independent.
        By applying the same arguments as in the previous cases and evaluating them at $x^+=k(e_{11}+e_{44})+e_{22}+e_{33}+e_{12}+e_{34}$, with $0\neq k \in F$, we get 
        $$
        -2\left( \sum_{i=0}^{n-1}(\gamma_i- \delta_i)k^i\right)e_{12}+2\left( \sum_{i=0}^{n-1}(\gamma_i+ \delta_i)k^{n-1-i}\right)e_{34}=0
        $$
        and, as a consequence, we have 
        \begin{equation*}
            \sum_{i=0}^{n-1}(\delta_i-\gamma_i)k^i=0, \quad  \quad
            \sum_{i=0}^{n-1}(\gamma_i+\delta_i)k^{n-1-i}=0.
        \end{equation*}
        Again, from the same argument of Case $1$ of the proof of  Lemma \ref{lemma: cn-1,1}, we obtain that 
        $\gamma_i=\delta_i=0$ for every $0 \leq i \leq n-1$. 

        Thus,  the $(W,*)$-polynomials $ t(x^+)$, $ t_{w_1^+}(x^+)$, $u^{(i)}(x^+)$,  and $u_{w_1^+}^{(i)}(x^+)$, for $0\leq i \leq n-1$, are linearly independent, and as in the previous cases, we obtain $m_{(n),\emptyset}\geq 2n+2$, as desired.

\label{th: cocharacter} 
Let $M^D$ be the $(W,*)$-algebra $M$ where $W$ acts on it as the algebra $D$ by left and right multiplication. For $n\geq 1$ and $0\leq r \leq n$, consider 
 $$\chi_{r,n-r}^{W,*}(M^D)=\sum_{(\lambda,\mu)\vdash (r,n-r)}m_{\lambda,\mu}(\chi_\lambda \otimes \chi_\mu),$$
 the $(r,n-r)$-th $(W,*)$-cocharacter of $M^D$.  Then: 
 \begin{enumerate}
 \item for $r=n$,
$$
m_{\lambda,\mu}= \begin{cases}
             4(q+1) & \text{if }\lambda=(p+q,p), \mu=\emptyset\\
             2(q+1) & \text{if } \lambda=(p+q,p,1), \mu=\emptyset\\
              2n+2 & \text{if } \lambda=(n),  \mu=\emptyset\\
              0 & \text{otherwise}\\
    \end{cases};
$$
\vspace{1mm}
     \item for $r=n-1$,
$$
m_{\lambda,\mu}= \begin{cases}
             2(q+1)  & \text{if } \lambda=(p+q,p),  \mu=(1)\\
              2n & \text{if }  \lambda=(n-1),  \mu=(1)\\
            0 & \text{otherwise}
    \end{cases};
$$
\vspace{1mm}

\item for $0\leq r \leq n-2$, we have $m_{\lambda,\mu}=0$.
 \end{enumerate}

Since $\mathcal{U}\subsetneq \mathcal{V}=\operatorname{var}^{W,*}(M^D)$,  there exist $ n \geq 1,$ $0\leq  r \leq n,$ and partitions $\lambda\vdash r$ and $\mu\vdash n-r$ such that $m_{\lambda,\mu}^{\mathcal{U}}<m_{\lambda,\mu}^{\mathcal{V}}$. Then, by Theorem \ref{th: cocharacter} we have that either
    \begin{equation}\label{eq: caso 1}
        \sum_{i=0}^q  \left(\alpha_i a_{p,q}^{(i)}(x_1^+,x_2^+,x^-)+ \beta_i a_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+,x^-)\right)\in \operatorname{Id}^{W,*}(\mathcal{U})
        \end{equation}
        with $\alpha_i,\beta_i$ not all zero, where the polynomials $a_{p,q}^{(i)}$ and $a_{p,q,w_1^+}^{(i)}$ are defined in \eqref{eq: a} and \eqref{eq: aw_1}, respectively, in the proof of Lemma \ref{lemma: cn-1,1}, or
        \begin{equation}\label{eq: case 2}
        \sum_{i=0}^{n-1}\left(\gamma_i b^{(i)}(x^+,x^-)+ \delta_i b_{w_1^+}^{(i)}(x^+,x^-)\right)\in \operatorname{Id}^{W,*}(\mathcal{U})
    \end{equation}
    with $\gamma_i,\delta_i$ not all zero, where the polynomials $b^{(i)}$ and $b_{w_1^+}^{(i)}$ are defined in \eqref{eq: b_i} and \eqref{eq: b_{w_1i}}, respectively, in the proof of Lemma \ref{lemma: cn-1,1}, or
    \begin{equation}\label{eq: case 3}
        \sum_{i=0}^{q} \left(\varepsilon_i f_{p,q}^{(i)}(x_1^+,x_2^+)+ \zeta_i f_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)+ \eta_i g_{p,q}^{(i)}(x_1^+,x_2^+)+ \theta_i g_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+)\right)\in \operatorname{Id}^{W,*}(\mathcal{U})
    \end{equation}
    with $\varepsilon_i,\zeta_i, \eta_i, \theta_i$ not all zero,  where the polynomials $f_{p,q}^{(i)}$, $f_{p,q,w_1^+}^{(i)}$, $g_{p,q}^{(i)}$ and $g_{p,q,w_1^+}^{(i)}$ are defined in \eqref{eq: f}, \eqref{eq: fw_1}, \eqref{eq: gi}, and \eqref{eq: gw_1}, respectively, in the proof of Lemma \ref{lemma: cn,0}, or
    \begin{equation}\label{eq: case 4}
        \sum_{i=0}^{q}\left(\nu_i h_{p,q}^{(i)}(x_1^+,x_2^+,x_3^+)+ \pi_i h_{p,q,w_1^+}^{(i)}(x_1^+,x_2^+,x_3^+)\right)\in \operatorname{Id}^{W,*}(\mathcal{U})
    \end{equation}
    with $\nu_i,\pi_i$ not all zero, where the polynomials $h_{p,q}^{(i)}$ and  $h_{p,q,w_1^+}^{(i)}$ are defined in \eqref{eq: h} and \eqref{eq: hw_1}, respectively, in the proof of Lemma \ref{lemma: cn,0}, or
     \begin{equation}\label{eq: case 5}
        \rho t(x^+)+\sigma t_{w_1^+}(x^+)+\sum_{i=0}^{n-1}\left(\tau_iu^{(i)}(x^+)+\xi_i u_{w_1^+}^{(i)}(x^+)\right)\in \operatorname{Id}^{W,*}(\mathcal{U})
  \end{equation}
    with $\rho,\sigma,\tau_i,\xi_i$ not all zero,  where the polynomials $t$, $t_{w_1^+}$, $u^{(i)}$, and $u_{w_1^+}^{(i)}$
    are defined in \eqref{eq: t}, \eqref{eq: tw1}, \eqref{eq: u}, and \eqref{eq: uw1}, respectively, in the proof of Lemma \ref{lemma: cn,0}.


