		\noindent\textbf{Case 1:} Suppose hold \eqref{eq: case 3}. Then
        \begin{align*}
&\sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}[x_1^+,x_2^+]\underbrace{\overline{x_2^+}\cdots \widetilde{x_2^+}}_{p-1}(x_1^+)^{q-i}v_i\\
&+\sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\left(x_1^+w_1^+x_2^+-x_2^+w_1^+x_1^+\right)\underbrace{\overline{x_2^+}\cdots \widetilde{x_2^+}}_{p-1}(x_1^+)^{q-i}v'_i\in \operatorname{Id}^{W,*}(\mathcal{U}),
\end{align*}
where $v_i := \varepsilon_i1_W+\zeta_iw_1^+\in W$ and $v'_i:= \eta_i1_W+\theta_iw_1^+\in W$  are not all zero.  If we substitute $x_2^+$ with $x_3^+ +x_4^+$, we obtain
\begin{align*}
&\sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}[x_1^+,x_3^++x_4^+]\underbrace{\overline{(x_3^+ +x_4^+)}\cdots \widetilde{(x_3^+ +x_4^+)}}_{p-1}(x_1^+)^{q-i}v_i\\
&+
\sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}
(x_1^+w_1^+(x_3^++x_4^+)-(x_3^++x_4^+)w_1^+x_1^+) \underbrace{\overline{(x_3^++x_4^+)}\cdots \widetilde{(x_3^++x_4^+)}}_{p-1}(x_1^+)^{q-i}v'_i \in \operatorname{Id}^{W,*}(\mathcal{U}).
\end{align*}
Now, consider the homogeneous component $c$ of degree $1$ in $x_4^+$. 

Since the $(W,*)$-polynomial  $[x_2^-,w_1^+]$ is symmetric, we may substitute $x_3^+$ by $(x_1^+)^2$ and $x_4^+$ by $[x_2^-,w_1^+]$ in $c$. Therefore, since the $(W,*)$-polynomial $x_1^+w_1^+(x_1^+)^2-(x_1^+)^2w_1^+x_1^+$ is skew-symmetric and $w_1^+x^-+x^-w_1^+,\, x_1^-x_2^-\in \operatorname{Id}^{W,*}(M^D)\subset \operatorname{Id}^{W,*}(\mathcal{U})$, by Lemma \ref{Lem: consequence x_1^- x_2^-} it follows that 
$$
\left(x_1^+w_1^+(x_1^+)^2-(x_1^+)^2w_1^+x_1^+\right) (x_1^+)^k [x_2^-,w_1^+], \  [x_2^-,w_1^+] (x_1^+)^k\left(x_1^+w_1^+(x_1^+)^2-(x_1^+)^2w_1^+x_1^+\right) \ \in  \operatorname{Id}^{W,*}(\mathcal{U})
$$
for all $k\geq 0$, and as a consequence, we have
\begin{align*}
&\sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\left( x_1^+[x_2^-,w_1^+]- [x_2^-,w_1^+]x_1^+ \right)\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{q-i}v_i\\
&
+ \sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}
(x_1^+w_1^+[x_2^-,w_1^+]-[x_2^-,w_1^+]w_1^+ x_1^+) \underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{q-i}v'_i \in \operatorname{Id}^{W,*}(\mathcal{U}).
\end{align*}
Since $[x_2^-,w_1^+]\equiv 2 x_2^-w_1^+ \pmod{\operatorname{Id}^{W,*}(M^D)}$ and $\operatorname{Id}^{W,*}(M^D)\subset \operatorname{Id}^{W,*}(\mathcal{U})$, also $[x_1^+,w_1^+]$ is skew-symmetric, $ x_1^-x_2^-\in \operatorname{Id}^{W,*}(M^D) \subset \operatorname{Id}^{W,*}(\mathcal{U})$ and by Lemma \ref{Lem: consequence x_1^- x_2^-}, we obtain
\begin{align*}
&\sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\left( x_1^+x_2^-- x_2^-x_1^+ \right)\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{q-i}v''_i\\
&
+ \sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}
(x_1^+w_1^+x_2^-w_1^+ -x_2^-(w_1^+)^2 x_1^+) \underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{q-i} v'''_i \in \operatorname{Id}^{W,*}(\mathcal{U}),
\end{align*}
where $v''_i:= 2\zeta_i1_W+ 2\varepsilon_iw_1^+\in W$ since $x^+ (w_1^+)^2- x^+ \in \operatorname{Id}^{W,*}(M^D) \subset \operatorname{Id}^{W,*}(\mathcal{U})$, $v'''_i:=2\eta_i1_W+2\theta_iw_1^+\in W$.
Now, since $(w_1^+)^2x^{+}-x^{+}, \, x^{+}(w_1^+)^2-x^{+}, \, w_1^+x_2^- +x_2^- w_1^+ \in \operatorname{Id}^{W,*}(M^D) \subset \operatorname{Id}^{W,*}(\mathcal{U})$, we get
$$
x_1^+w_1^+x_2^- w_1^+ -x_2^- (w_1^+)^2x_1^+\equiv -x_1^+x_2^- -x_2^- x_1^+ \pmod{\operatorname{Id}^{W,*}(\mathcal{U})},
$$
and so it follows that
\begin{equation*}\label{eq: c(x_1,x_2)'}
\begin{split}
&\sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}[x_1^+,x_2^-]\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{q-i}v''_i\\
&
- \sum_{i=0}^q(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}
(x_1^+ x_2^- + x_2^- x_1^+)\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{q-i}v'''_i \ \in \operatorname{Id}^{W,*}(\mathcal{U}),
\end{split}
\end{equation*}
 where $v''_i= 2\zeta_i1_W+ 2\varepsilon_iw_1^+\in W$ and $v'''_i=2\eta_i1_W+2\theta_iw_1^+\in W$ are not all zero.


Let $t$ be the maximum $i$ such that $v''_i\neq 0$ or $v'''_i\neq 0$.  Since $[x_1^+,w_1^+]$ is skew-symmetric and $x_1^-x_2^-\in \operatorname{Id}^{W,*}(M^D)\subset \operatorname{Id}^{W,*}(\mathcal{U}) $, we can move $v''_i, \, v'''_i$ and obtain 
\begin{equation}\label{eq: c(x_1,x_2)}
\begin{split}
&(x_1^+)^t\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\left( [x_1^+,x_2^-]v''_t- (x_1^+ x_2^- + x_2^- x_1^+) v'''_t\right)\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{q-t}\\
&+\sum_{i<t}(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\left( [x_1^+,x_2^-]v''_i- (x_1^+ x_2^- + x_2^- x_1^+) v'''_i\right)\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{q-i} \ \in \operatorname{Id}^{W,*}(\mathcal{U}).
\end{split}
\end{equation}
First, observe that we may assume, without loss of generality, that $t=q-t$. Indeed, if $t<q-t$, we multiply \eqref{eq: c(x_1,x_2)} on the left by $(x_1^+)^{q-2t}$,             




thereby reducing to the case $t=q-t$.
Similarly, if $t>q-t$, we can multiply \eqref{eq: c(x_1,x_2)} on the right by $(x_1^+)^{2t-q}$. Hence, \eqref{eq: c(x_1,x_2)} becomes
\begin{equation*}
\begin{split}
r(x_1^+,x_2^-):=&(x_1^+)^t\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\left( [x_1^+,x_2^-]v''_t- (x_1^+ x_2^- + x_2^- x_1^+) v'''_t\right)\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{t}\\
&+\sum_{i<t}(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\left( [x_1^+,x_2^-]v''_i- (x_1^+ x_2^- + x_2^- x_1^+) v'''_i\right)\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{2t-i} \ \in \operatorname{Id}^{W,*}(\mathcal{U}),
\end{split}
\end{equation*}
with $v''_j= 2\zeta_j1_W+ 2\varepsilon_jw_1^+\in W$ and $v'''_j=2\eta_j1_W+2\theta_jw_1^+\in W$.
Since $(r(x_1^+,x_2^-))^*\in \operatorname{Id}^{W,*}(\mathcal{U})$, by Lemma \ref{lem: Id} we have
\begin{equation*}
\begin{split}
r'(x_1^+,x_2^-):=&(x_1^+)^t\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\left( [x_1^+,x_2^-]u_t- (x_1^+ x_2^- + x_2^- x_1^+) u'_t\right)\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{t}\\
&+\sum_{i<t}(x_1^+)^i\underbrace{\overline{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\left( [x_1^+,x_2^-]u_i- (x_1^+ x_2^- + x_2^- x_1^+) u'_i\right)\underbrace{\overline{(x_1^+)^2}\cdots \widetilde{(x_1^+)^2}}_{p-1}(x_1^+)^{2t-i} \ \in \operatorname{Id}^{W,*}(\mathcal{U}),
\end{split}
\end{equation*}
 where $u_t= 2\zeta_t1_W- 2\varepsilon_tw_1^+\in W$, $u'_t=-2\eta_t1_W+2\theta_tw_1^+\in W$, and for $i<t$, $u_i= 2\zeta_{2t-i}1_W- 2\varepsilon_{2t-i}w_1^+\in W$ and $u'_i=-2\eta_{2t-i}1_W+2\theta_{2t-i}w_1^+\in W$. 
Moreover, notice that 
$$v''_t+u_t=4\zeta_t1_W, \quad v'''_t+u'_t=4\theta_tw_1^+, \quad v''_t-u_t=4\varepsilon_tw_1^+, \quad    v'''_t-u'_t=4\eta_t1_W.$$


Suppose first that $\zeta_t\neq 0$ or $\theta_t\neq 0$ and  set $N=q+3p-2.$ Since  $r(x_1^+,x_2^-)+ r'(x_1^+,x_2^-)\in \operatorname{Id}^{W,*}(\mathcal{U}),$ we have 
\begin{equation*}
\begin{split}
\zeta_t(x_1^+)^{t+2p-1} x_2^- (x_1^+)^{N-t-2p+1}  &-\theta_t(x_1^+)^{t+2p-1} x_2^- (x_1^+)^{N-t-2p+1} w_1^+\\ &+\sum_{i<t+2p-1} \beta'_i(x_1^+)^{i} x_2^- (x_1^+)^{N-i} +\sum_{i<t+2p-1} \gamma'_i(x_1^+)^{i} x_2^- (x_1^+)^{N-i} w_1^+ \ \in \operatorname{Id}^{W,*}(\mathcal{U}),
\end{split}
\end{equation*}
for some $\beta'_i, \gamma'_i\in F$. Since  $\zeta_t\neq 0$ or $\theta_t\neq 0$ and and $x^{\epsilon}(w_1^+)^2-x^{\epsilon} \in  \operatorname{Id}^{W,*}(M^D)\subset  \operatorname{Id}^{W,*}(\mathcal{U})$, $\epsilon\in \{+,-\}$, we have 
 \begin{align*}
    (x_1^+)^{t_1+2p-1}x_2^- (x_1^+)^{N-t_1-2p+1} &+ \hat{\alpha} (x_1^+)^{t_1+2p-1}x_2^- (x_1^+)^{N-t_1-2p+1} w_1^+ \\
    &+\sum_{i<t_1+2p-1}\hat{\beta}_i(x_1^+)^ix_2^-(x_1^+)^{N-i} +\sum_{i<t_1+2p-1}\hat{\gamma}_i(x_1^+)^ix_2^-(x_1^+)^{N-i}w_1^+ \ \in \operatorname{Id}^{W,*}(\mathcal{U}),
\end{align*}
for some $\hat{\alpha}, \hat{\beta}_i, \hat{\gamma}_i \in F$. Hence, setting $K:=t+2p-1$ gives the desired conclusion.

If $\zeta_t=\theta_t = 0$, then $\varepsilon_t\neq 0$ or $\eta_t\neq 0$. Thus, since $r(x_1^+,x_2^-)- r'(x_1^+,x_2^-)\in \operatorname{Id}^{W,*}(\mathcal{U}),$ by proceeding as above we obtain the desired conclusion.




