\noindent\textbf{Case 5:} Suppose hold \eqref{eq: case 4}. Since 
\begin{align*}
		   h_{p,q}^{(i)}(x_1^+,x_2^+,x_3^+)&=(x_1^+)^i\underbrace{\widehat{x_1^+}\cdots \widetilde{x_1^+}}_{p-1}\overline{x_1^+}\,\overline{x_2^+} \,\overline{x_3^+}\underbrace{\widehat{x_2^+}\cdots \widetilde{x_2^+}}_{p-1}(x_1^+)^{q-i},\\
